from __future__ import annotations

import sqlite3

VERSION = 2


def create_canonical(connection: sqlite3.Connection) -> None:
    statements = [
        "CREATE TABLE canonical_providers(id TEXT PRIMARY KEY NOT NULL REFERENCES identity_registry(id), display_name TEXT NOT NULL CHECK(length(trim(display_name))>0)) STRICT",
        "CREATE TABLE canonical_properties(id TEXT PRIMARY KEY NOT NULL REFERENCES identity_registry(id), house_number INTEGER CHECK(house_number>0), street TEXT, unit TEXT, unit_state TEXT NOT NULL CHECK(unit_state IN ('known','none','unknown','conflicting')), city TEXT, state TEXT, postal_code TEXT, latitude REAL, longitude REAL, geocode_precision TEXT NOT NULL CHECK(geocode_precision IN ('missing','street_segment_interpolation')), reference_segment_id TEXT REFERENCES street_segments(id), CHECK((unit_state='known' AND unit IS NOT NULL) OR (unit_state<>'known' AND unit IS NULL)), CHECK((latitude IS NULL)=(longitude IS NULL)), CHECK(latitude BETWEEN -90 AND 90), CHECK(longitude BETWEEN -180 AND 180), CHECK((geocode_precision='missing' AND latitude IS NULL) OR (geocode_precision='street_segment_interpolation' AND latitude IS NOT NULL AND reference_segment_id IS NOT NULL))) STRICT",
        "CREATE TABLE canonical_jobs(id TEXT PRIMARY KEY NOT NULL REFERENCES identity_registry(id), provider_id TEXT NOT NULL REFERENCES canonical_providers(id), property_id TEXT REFERENCES canonical_properties(id), property_link_state TEXT NOT NULL CHECK(property_link_state IN ('resolved','missing','unresolved','conflicting')), lifecycle TEXT NOT NULL CHECK(lifecycle IN ('open','active','pending_approval','completed','cancelled','unknown')), amount_minor INTEGER, currency TEXT, amount_state TEXT NOT NULL CHECK(amount_state IN ('known','missing','disputed')), CHECK((property_link_state='resolved')=(property_id IS NOT NULL)), CHECK((amount_state='known' AND amount_minor IS NOT NULL AND currency IS NOT NULL AND length(currency)=3) OR (amount_state IN ('missing','disputed') AND amount_minor IS NULL))) STRICT",
        "CREATE TABLE canonical_estimates(id TEXT PRIMARY KEY NOT NULL REFERENCES identity_registry(id), provider_id TEXT NOT NULL REFERENCES canonical_providers(id), property_id TEXT REFERENCES canonical_properties(id), property_link_state TEXT NOT NULL CHECK(property_link_state IN ('resolved','missing','unresolved','conflicting')), estimate_state TEXT NOT NULL CHECK(estimate_state IN ('open','scheduled','in_progress','completed','cancelled','unknown')), CHECK((property_link_state='resolved')=(property_id IS NOT NULL))) STRICT",
        "CREATE TABLE trades(code TEXT PRIMARY KEY NOT NULL,label TEXT NOT NULL) STRICT",
        "CREATE TABLE service_categories(code TEXT PRIMARY KEY NOT NULL,label TEXT NOT NULL) STRICT",
        "CREATE TABLE service_category_trades(service_code TEXT NOT NULL REFERENCES service_categories(code),trade_code TEXT NOT NULL REFERENCES trades(code),PRIMARY KEY(service_code,trade_code)) STRICT",
        "CREATE TABLE provider_aliases(id TEXT PRIMARY KEY NOT NULL,provider_id TEXT NOT NULL REFERENCES canonical_providers(id),name TEXT NOT NULL,normalized_name TEXT NOT NULL,UNIQUE(provider_id,normalized_name)) STRICT",
        "CREATE TABLE provider_trades(provider_id TEXT NOT NULL REFERENCES canonical_providers(id),trade_code TEXT NOT NULL REFERENCES trades(code),PRIMARY KEY(provider_id,trade_code)) STRICT",
        "CREATE TABLE provider_exclusions(provider_id TEXT NOT NULL REFERENCES canonical_providers(id),trade_code TEXT NOT NULL REFERENCES trades(code),PRIMARY KEY(provider_id,trade_code)) STRICT",
        "CREATE TABLE provider_declared_service_areas(provider_id TEXT NOT NULL REFERENCES canonical_providers(id),postal_code TEXT NOT NULL CHECK(length(postal_code)=5 AND postal_code NOT GLOB '*[^0-9]*'),PRIMARY KEY(provider_id,postal_code)) STRICT",
        "CREATE TABLE reconciliation_proposals(id TEXT PRIMARY KEY NOT NULL,document TEXT NOT NULL) STRICT",
        "CREATE TABLE reconciliation_metadata(ledger_revision TEXT NOT NULL,stale_decisions TEXT NOT NULL,rule_version TEXT NOT NULL) STRICT",
        "CREATE TABLE canonical_crosswalk(source_id TEXT NOT NULL REFERENCES source_records(id),kind TEXT NOT NULL,canonical_id TEXT NOT NULL,rule TEXT NOT NULL,evidence TEXT NOT NULL,PRIMARY KEY(source_id,kind),FOREIGN KEY(canonical_id,kind) REFERENCES identity_registry(id,kind)) STRICT",
        "CREATE TABLE field_lineage(entity_id TEXT NOT NULL REFERENCES lineage_entities(id),field TEXT NOT NULL REFERENCES lineage_fields(code),source_id TEXT NOT NULL REFERENCES source_records(id),rule TEXT NOT NULL,decision_id TEXT,PRIMARY KEY(entity_id,field,source_id,rule)) STRICT",
    ]
    connection.execute("CREATE TABLE lineage_entities(id TEXT PRIMARY KEY NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('provider','property','job','estimate','visit','job_service','estimate_service','completion'))) STRICT")
    connection.execute("CREATE TABLE lineage_fields(code TEXT PRIMARY KEY NOT NULL) STRICT")
    connection.executemany("INSERT INTO lineage_fields VALUES(?)",[(field,) for field in ('display_name','capabilities','address','unit','postal_code','city','state','coordinates','service_code','lifecycle','estimate_state','property_id','scheduled_start','scheduled_end','scheduling_state','amount_minor','currency','service_date','completed_at')])
    for statement in statements:
        connection.execute(statement)
    for parent in ('job','estimate'):
        connection.execute(f"CREATE TABLE {parent}_services(id TEXT PRIMARY KEY NOT NULL,{parent}_id TEXT NOT NULL REFERENCES canonical_{parent}s(id),trade_code TEXT NOT NULL,service_code TEXT NOT NULL,safe_description TEXT NOT NULL,classification_state TEXT NOT NULL CHECK(classification_state IN ('mapped','unmapped','conflicting')),FOREIGN KEY(service_code,trade_code) REFERENCES service_category_trades(service_code,trade_code),UNIQUE({parent}_id,trade_code,service_code)) STRICT")
    endpoints = []
    checks = []
    for endpoint in ('start','end'):
        prefix = 'scheduled_'+endpoint
        endpoints.extend([f'{prefix}_utc TEXT',f'{prefix}_local_date TEXT',f"{prefix}_state TEXT NOT NULL CHECK({prefix}_state IN ('known','missing','ambiguous','disputed'))",f"{prefix}_precision TEXT NOT NULL CHECK({prefix}_precision IN ('instant','date','unknown'))"])
        checks.append(f"CHECK(({prefix}_state='known' AND (({prefix}_precision='instant' AND {prefix}_utc IS NOT NULL AND {prefix}_local_date IS NOT NULL) OR ({prefix}_precision='date' AND {prefix}_utc IS NULL AND {prefix}_local_date IS NOT NULL))) OR ({prefix}_state='missing' AND {prefix}_precision='unknown' AND {prefix}_utc IS NULL AND {prefix}_local_date IS NULL) OR ({prefix}_state IN ('ambiguous','disputed') AND {prefix}_utc IS NULL AND (({prefix}_precision='date' AND {prefix}_local_date IS NOT NULL) OR ({prefix}_precision='unknown' AND {prefix}_local_date IS NULL))))")
    connection.execute("CREATE TABLE canonical_visits(id TEXT PRIMARY KEY NOT NULL REFERENCES identity_registry(id),job_id TEXT REFERENCES canonical_jobs(id),estimate_id TEXT REFERENCES canonical_estimates(id),appointment_kind TEXT NOT NULL CHECK(appointment_kind IN ('job','estimate')),scheduling_state TEXT NOT NULL CHECK(scheduling_state IN ('scheduled','in_progress','completed','cancelled','overdue','unscheduled','superseded','unknown')),"+','.join(endpoints)+",timezone_name TEXT NOT NULL,CHECK((appointment_kind='job' AND job_id IS NOT NULL AND estimate_id IS NULL) OR (appointment_kind='estimate' AND estimate_id IS NOT NULL AND job_id IS NULL)),CHECK(scheduled_end_utc IS NULL OR scheduled_start_utc IS NULL OR scheduled_end_utc>scheduled_start_utc),UNIQUE(id,job_id),"+','.join(checks)+") STRICT")
    connection.execute("CREATE TABLE service_completions(id TEXT PRIMARY KEY NOT NULL,job_id TEXT NOT NULL REFERENCES canonical_jobs(id),visit_id TEXT UNIQUE,evidence_basis TEXT NOT NULL CHECK(evidence_basis IN ('completed_visit','job_completion_timestamp','job_completed_status')),service_date TEXT,service_date_state TEXT NOT NULL CHECK(service_date_state IN ('known','missing','ambiguous','disputed')),service_date_basis TEXT NOT NULL CHECK(service_date_basis IN ('completion_timestamp','completed_visit_schedule','completed_job_schedule','unknown')),completed_at_utc TEXT,completed_at_state TEXT NOT NULL CHECK(completed_at_state IN ('known','missing','ambiguous','disputed')),FOREIGN KEY(visit_id,job_id) REFERENCES canonical_visits(id,job_id),CHECK((completed_at_state='known')=(completed_at_utc IS NOT NULL)),CHECK(service_date_state<>'missing' OR service_date IS NULL),CHECK(service_date_state<>'known' OR service_date IS NOT NULL),CHECK((evidence_basis='completed_visit')=(visit_id IS NOT NULL))) STRICT")
    connection.execute("CREATE TABLE completion_evidence(completion_id TEXT NOT NULL REFERENCES service_completions(id),source_id TEXT NOT NULL REFERENCES source_records(id),PRIMARY KEY(completion_id,source_id)) STRICT")
    connection.execute("CREATE TABLE completion_services(completion_id TEXT NOT NULL REFERENCES service_completions(id),job_service_id TEXT NOT NULL REFERENCES job_services(id),PRIMARY KEY(completion_id,job_service_id)) STRICT")
    connection.execute("CREATE TRIGGER completion_service_job BEFORE INSERT ON completion_services WHEN (SELECT job_id FROM service_completions WHERE id=NEW.completion_id)<>(SELECT job_id FROM job_services WHERE id=NEW.job_service_id) BEGIN SELECT RAISE(ABORT,'completion service belongs to another job'); END")
    connection.execute("CREATE TRIGGER completion_service_job_update BEFORE UPDATE ON completion_services WHEN (SELECT job_id FROM service_completions WHERE id=NEW.completion_id)<>(SELECT job_id FROM job_services WHERE id=NEW.job_service_id) BEGIN SELECT RAISE(ABORT,'completion service belongs to another job'); END")
    connection.execute("CREATE TRIGGER completion_parent_guard BEFORE UPDATE OF job_id ON service_completions WHEN EXISTS(SELECT 1 FROM completion_services cs JOIN job_services js ON js.id=cs.job_service_id WHERE cs.completion_id=OLD.id AND js.job_id<>NEW.job_id) BEGIN SELECT RAISE(ABORT,'completion service belongs to another job'); END")
    connection.execute("CREATE TRIGGER service_parent_guard BEFORE UPDATE OF job_id ON job_services WHEN EXISTS(SELECT 1 FROM completion_services cs JOIN service_completions c ON c.id=cs.completion_id WHERE cs.job_service_id=OLD.id AND c.job_id<>NEW.job_id) BEGIN SELECT RAISE(ABORT,'completion service belongs to another job'); END")
    connection.execute('CREATE INDEX completion_job_stamp ON service_completions(job_id,completed_at_utc)')
    for table,kind in [('canonical_providers','provider'),('canonical_properties','property'),('canonical_jobs','job'),('canonical_estimates','estimate'),('canonical_visits','visit')]:
        for operation in ('INSERT','UPDATE OF id'):
            suffix='insert' if operation=='INSERT' else 'update'
            connection.execute(f"CREATE TRIGGER {table}_identity_{suffix} BEFORE {operation} ON {table} WHEN (SELECT kind FROM identity_registry WHERE id=NEW.id)<>'{kind}' BEGIN SELECT RAISE(ABORT,'canonical identity kind mismatch'); END")
    lineage_tables={'provider':'canonical_providers','property':'canonical_properties','job':'canonical_jobs','estimate':'canonical_estimates','visit':'canonical_visits','job_service':'job_services','estimate_service':'estimate_services','completion':'service_completions'}
    for kind,table in lineage_tables.items():
        for operation in ('DELETE','UPDATE OF id'):
            suffix='delete' if operation=='DELETE' else 'move'
            connection.execute(f"CREATE TRIGGER lineage_{kind}_{suffix} BEFORE {operation} ON {table} WHEN EXISTS(SELECT 1 FROM lineage_entities WHERE id=OLD.id AND kind='{kind}') BEGIN SELECT RAISE(ABORT,'entity has lineage references'); END")
        for operation in ('INSERT','UPDATE'):
            connection.execute(f"CREATE TRIGGER lineage_{kind}_{operation.lower()} BEFORE {operation} ON lineage_entities WHEN NEW.kind='{kind}' AND NOT EXISTS(SELECT 1 FROM {table} WHERE id=NEW.id) BEGIN SELECT RAISE(ABORT,'unknown lineage entity'); END")
    for name,table,columns in [('crosswalk_canonical','canonical_crosswalk','canonical_id,kind'),('completion_service_lookup','completion_services','job_service_id'),('jobs_provider','canonical_jobs','provider_id'),('jobs_property','canonical_jobs','property_id'),('property_location','canonical_properties','street,city,state,house_number'),('property_geo','canonical_properties','latitude,longitude'),('visits_window','canonical_visits','scheduled_start_utc,scheduled_end_utc'),('completion_window','service_completions','service_date,job_id'),('services_trade','job_services','trade_code,job_id')]:
        connection.execute(f'CREATE INDEX {name} ON {table}({columns})')
